select p_type, COUNT(*) from lineorder, dwdate, part, supplier where lo_orderdate = d_datekey and lo_partkey = p_partkey and lo_suppkey = s_suppkey and s_region = 'AMERICA' and d_weeknuminyear = 6 and lo_quantity>=5 group by p_type;
select p_brand1, COUNT(*) from lineorder, dwdate, part, supplier where lo_orderdate = d_datekey and lo_partkey = p_partkey and lo_suppkey = s_suppkey and s_region = 'AMERICA' and d_weeknuminyear = 6 and lo_quantity>=5 group by p_brand1;
select p_name, COUNT(*) from lineorder, dwdate, part, supplier where lo_orderdate = d_datekey and lo_partkey = p_partkey and lo_suppkey = s_suppkey and s_region = 'AMERICA' and d_weeknuminyear = 6 and lo_quantity>=5 group by p_name;
